# The input mappers' mutants, .ANM. Dropped as equivalent, each with its reason:
#   * The order in which UnbindFrom or Release zero their fields, and of the list's constructor's zeroes: nothing reads between them.
#   * m_axisMaps' free guarded by the capacity rather than the pointer: with a capacity the pointer is held, unless a heap failed, and then the read has already crashed.
#   * The list's second loop in Remove on a full list, reading one past the end: that word is only compared with the link, and equal only by chance.
#   * The second word of the two list destructors' forms is the same code as Clear: each is mutated on its own below.
#   * Removing GmNameMap::Clear() from the database's destructor: the base destructor, which runs next, does the same clear.
#   * Removing file.Close() from Load: the token file's destructor, which runs at once, does the same close.
M = "AtInputMapper.cpp"
R = "AtInputRouter.cpp"

_LINE_BTN = "            do {\n                switch (token) {\n"
_PHYS_B = "                case kPhysicalID:\n                    physical = tokenizer->Next();\n                    if (physical < kFirstInputCode) {\n                        tokenizer->Error(AtIoTokenizer::kExpectedKeyword);\n                    }\n"
_ABS_B = "                case kAbstractID:\n                    abstractId = tokenizer->Next();\n                    if (abstractId < kFirstInputCode) {\n                        tokenizer->Error(AtIoTokenizer::kExpectedKeyword);\n                    }\n"
_PHYS_A = "            case kPhysicalID:\n                physical = tokenizer->Next();\n                if (physical < kFirstInputCode) {\n                    tokenizer->Error(AtIoTokenizer::kExpectedKeyword);\n                }\n"
_ABS_A = "            case kAbstractID:\n                abstractId = tokenizer->Next();\n                if (abstractId < kFirstInputCode) {\n                    tokenizer->Error(AtIoTokenizer::kExpectedKeyword);\n                }\n"
_MDTOR = "AtInputMapperDatabase::~AtInputMapperDatabase() {\n    if (m_items != 0) {\n        AtDeleteArray(m_items);\n        m_owner = 0;\n        m_items = 0;\n        m_unknown1C = 0;\n        GmNameMap::Clear();\n"
_MCLEAR = "void AtInputMapperDatabase::Clear() {\n    if (m_items != 0) {\n        AtDeleteArray(m_items);\n        m_owner = 0;\n        m_items = 0;\n        m_unknown1C = 0;\n        GmNameMap::Clear();\n"
_LDTOR = "AtInputLinkList::~AtInputLinkList() {\n    if (m_items != 0) {\n        operator delete(m_items);\n    }\n    m_items = 0;\n    m_count = 0;\n    m_capacity = 0;\n"
_LCLEAR = "void AtInputLinkList::Clear() {\n    if (m_items != 0) {\n        operator delete(m_items);\n    }\n    m_items = 0;\n    m_count = 0;\n    m_capacity = 0;\n"
_MAPCLEAR = "    m_router.Release();\n    if (m_buttonMaps != 0) {\n        operator delete(m_buttonMaps);\n    }\n    if (m_axisMapCapacity != 0) {\n        operator delete(m_axisMaps);\n    }\n    m_device = 0;\n    m_buttonMaps = 0;\n    m_axisMaps = 0;\n    m_buttonMapCapacity = 0;\n    m_buttonMapsUsed = 0;\n    m_axisMapCapacity = 0;\n    m_axisMapsUsed = 0;\n"
_MAPCTOR = "AtInputMapper::AtInputMapper() {\n    m_device = 0;\n    m_buttonMaps = 0;\n    m_axisMaps = 0;\n    m_buttonMapCapacity = 0;\n    m_buttonMapsUsed = 0;\n    m_axisMapCapacity = 0;\n    m_axisMapsUsed = 0;\n"
_RCTOR = "AtInputRouter::AtInputRouter() {\n    m_freeFirst = 0;\n    m_freeLast = 0;\n    m_device = 0;\n    m_buttonLinks = 0;\n    m_axisLinks = 0;\n    m_bindFunction = 0;\n    m_passOnTo = 0;\n"
_RREL = "    if (m_axisLinks != 0) {\n        operator delete(m_axisLinks);\n    }\n    m_device = 0;\n    m_buttonLinks = 0;\n    m_axisLinks = 0;\n    m_bindFunction = 0;\n    m_passOnTo = 0;\n"
_UNBIND_B = "            controller->UnbindButton(link);\n            PushFree(this, link);\n            m_boundButtons.Remove(link);\n            i = (unsigned int)-1;  // From the start again.\n"
_UNBIND_A = "                controller->UnbindAxis(link);\n                PushFree(this, link);\n                m_boundAxes.Remove(link);\n                i = (unsigned int)-1;\n"
_ALLB = "        link->m_controller->UnbindButton(link);\n        m_boundButtons.Remove(link);\n        PushFree(this, link);\n"
_ALLA = "        link->m_controller->UnbindAxis(link);\n        m_boundAxes.Remove(link);\n        PushFree(this, link);\n"


